__NUXT_JSONP__("/posts/new-blog-version-with-nuxt", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G){return {data:[{post:{slug:w,description:"Why I migrated my blog from Wordpress to Nuxt",title:"New blog version with Nuxt",type:f,imgCover:w,tags:[s,t,u,x,f],createdAt:"2021-01-30T00:00:00.000Z",toc:[{id:y,depth:l,text:z},{id:A,depth:l,text:B},{id:C,depth:l,text:D},{id:u,depth:l,text:v},{id:E,depth:l,text:F}],body:{type:"root",children:[{type:b,tag:m,props:{id:y},children:[{type:b,tag:d,props:{href:"#reasons-to-migrate-from-wordpress-to-nuxt",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:z}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"It's been 2 years I made the switch to Vue.js as my go-to solution to build websites and I decided it was time to migrate my wordpress blog to the stack I'm using on a daily basis."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Wordpress has made a great job so far, but I found the latency between page queries annoying, and I didn't enjoy using the clutered Wordpress admin as well as maintaining a bunch of always outdated plugins."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Regarding the stack, "},{type:b,tag:d,props:{href:"https:\u002F\u002Fgridsome.org\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Gridsome"}]},{type:a,value:" has been my favorite meta-framework to build static sites for a while, but I moved my focus on "},{type:b,tag:d,props:{href:"https:\u002F\u002Fnuxtjs.org\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Nuxt"}]},{type:a,value:" for the last few months, as I think it's more versatile, has a bigger community, and also has a faster development pace."}]},{type:a,value:c},{type:b,tag:m,props:{id:A},children:[{type:b,tag:d,props:{href:"#nuxt-content-as-cms",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:B}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"This migration has been the opportunity to deep-dive into the relatively young "},{type:b,tag:d,props:{href:"https:\u002F\u002Fcontent.nuxtjs.org\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"nuxt\u002Fcontent"}]},{type:a,value:" module as a content management solution. It self describes as a git-based headless CMS. Though, we have to make a distinction between solutions offering an UI for contributors (Prismic, Contentful, Wordpress...), and nuxt\u002Fcontent as it's really aimed for developers who want to edit markdown files locally."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I then rolled up my sleeves and proceeded to manually migrate all content into a new set of markdown files. The writing experience is just about writing regular markdown, but with additional features such as adding vue components in the middle of our body content, even pass props inside. There's a lot of possibilities like creating an auto generated table of content, description, or using other file types (json, yml..)."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Nuxt\u002Fcontent offers a really "},{type:b,tag:d,props:{href:"https:\u002F\u002Fcontent.nuxtjs.org\u002Ffetching",rel:[g,h,i],target:j},children:[{type:a,value:"simple API"}]},{type:a,value:" to fetch data, sort, filter, limit, or perform a query. I took advantage of these features to easily build a post filter feature."}]},{type:a,value:c},{type:b,tag:m,props:{id:C},children:[{type:b,tag:d,props:{href:"#images",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:D}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"If one thing is still missing in Nuxt to my opinion, it's a convenient image component to offer responsive sizes on the fly + progressive behavior. Gridsome has the \u003Cg-image\u003E component for this. Nuxt has a new "},{type:b,tag:d,props:{href:"https:\u002F\u002Fimage.nuxtjs.org\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"nuxt\u002Fimage"}]},{type:a,value:" module but it's not production ready. I attempted to use this at first, but it completely messed up at build. I look forward for a stable release as it seems very promising!"}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"So at the end, I used "},{type:b,tag:d,props:{href:"https:\u002F\u002Fcloudinary.com\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Cloudinary"}]},{type:a,value:" as CDN solution to deliver optimized images on the fly. I used Cloudinary multiple times, it's a powerful solution, though the documentation is a bit overwhelming to me as paramaters are endless... I don't fancy that much relying on a CDN to display a bunch of images I could host along the app, but this is the most performant solution I found so far for this use-case."}]},{type:a,value:c},{type:b,tag:m,props:{id:u},children:[{type:b,tag:d,props:{href:"#cypress",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:v}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"This refactoring has also been the opportunity to give a try to "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.cypress.io\u002F",rel:[g,h,i],target:j},children:[{type:a,value:v}]},{type:a,value:", the famous end-to-end test framework."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Though using this tool on such a project can be considered a bit over-engeneering, I think it's the perfect sandbox to explore its inner workflow. The goal is to give confidence regarding releases. I started with a bunch of simple assertions with very simple scenarios, as well as testing the filter feature to make sure it works properly."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I really like the visual "},{type:b,tag:d,props:{href:"https:\u002F\u002Fdocs.cypress.io\u002Fguides\u002Fcore-concepts\u002Ftest-runner.html#Overview",rel:[g,h,i],target:j},children:[{type:a,value:"test-runner"}]},{type:a,value:", which is part of the Cypress toolkit. The documentation is very complete and user-friendly."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"From now on, I will implement E2E tests into every project including cumbersome smoke tests such as form testing."}]},{type:a,value:c},{type:b,tag:m,props:{id:E},children:[{type:b,tag:d,props:{href:"#stack--repo",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:F}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"To sum up, here is the stack\u002Fservices I used for this project :"}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"Nuxt as Vue static site generator"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"Nuxt\u002Fcontent as headless CMS"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"Tailwind CSS as CSS framework"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"Vue-infinite loading as infinite scroll handler"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"Nuxt\u002Fsvg as SVG handler"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"Cypress as end-to-end testing framework"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"Cloudinary as images hosting platform"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"Netlify as hosting plateform"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I setup the codebase as a "},{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Flansolo99\u002Flansolo.dev",rel:[g,h,i],target:j},children:[{type:a,value:"public git repo"}]},{type:a,value:" if you ever interested to take a glance."}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Fnew-blog-version-with-nuxt",extension:".md",updatedAt:"2025-10-10T15:29:17.525Z"},relatedPosts:[{title:"Nuxt.js puzzle game development - WIP#3",type:f,imgCover:"nuxt-js-puzzle-game-development-wip3",tags:[s,"cordova","games",f],createdAt:"2019-11-21T00:00:00.000Z",path:"\u002Fposts\u002Fnuxt-js-puzzle-game-development-wip3"},{title:"JS frameworks switching",type:f,imgCover:"js-frameworks-switching.jpg",tags:[t,s,"gridsome","quasar","react",G,"svelte","miscs",f],createdAt:"2022-10-19T00:00:00.000Z",path:"\u002Fposts\u002Fjs-frameworks-switching"},{title:"Red Teamer: Building a Button-Based AI Chatbot Game",type:f,imgCover:"red-teamer-building-a-button-based-ai-chatbot-game",tags:["game",G,"framer-motion","Tailwind","Figma",x,"cinema 4D","AI",f],createdAt:"2025-09-07T00:00:00.000Z",path:"\u002Fposts\u002Fred-teamer-building-a-button-based-ai-chatbot-game"},{title:"Todo vue.js app WIP#2 : vuex modules + Firebase",type:f,imgCover:"todo-vue-js-app-wip2-vuex-modules-firebase",tags:[t,"sketch",f],createdAt:"2019-03-03T00:00:00.000Z",path:"\u002Fposts\u002Ftodo-vue-js-app-wip2-vuex-modules-firebase"}]}],fetch:[{counter:15},{counter:13},{counter:l},{counter:32},{counter:72}],mutations:[]}}("text","element","\n","a","p","article","nofollow","noopener","noreferrer","_blank","li",2,"h2","true",-1,"span","icon","icon-link","nuxt","vue","cypress","Cypress","new-blog-version-with-nuxt","devs","reasons-to-migrate-from-wordpress-to-nuxt","Reasons to migrate from Wordpress to Nuxt","nuxt-content-as-cms","Nuxt-content as CMS","images","Images","stack--repo","Stack & repo","next")));